static void Check(bool ok,const std::string& why){if(!ok)throw std::runtime_error(why);++checks;std::cerr<<checks<<": "<<why<<"\n";}
template<class F>static void Reject(F f,const std::string& why){bool failed=false;try{f();}catch(const std::exception&){failed=true;}Check(failed,why);}
static Entity Node(World& w,const std::string& name){auto e=w.CreateEntity();w.AddComponent<TransformComponent>(e);w.AddComponent<TagComponent>(e).name=name;w.AddComponent<SceneIdentityComponent>(e);return e;}
static Json& Member(Json& data,const std::string& id){for(auto& n:data.at("entities"))if(n.at("id")==id)return n;throw std::runtime_error("Missing member "+id);}
static Entity Named(World& w,const std::string& name){for(auto e:w.Entities())if(auto* t=w.GetComponent<TagComponent>(e);t&&t->name==name)return e;throw std::runtime_error("Missing entity "+name);}
static std::string Bytes(const fs::path& p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
